#!/usr/bin/env bash
# Controlled A/B for #14075, per the revised acceptance (msg_4199351d).
#
#   control   = the delivered tree with ONLY src/v1/04_infer.dag and its stage0 mirror
#               swapped to the merge-base pair (.sdm/pairs/control/), i.e. the OLD
#               second-pass algorithm, regenerated by the seed's own writer.
#   keep      = candidate as committed (.sdm/dag_variants/keep)  -- gate deleted,
#               stale-expression subsystem retained.
#   delete    = .sdm/dag_variants/delete -- also drops typed_expr_is_stale /
#               recheck_expr (the item-5 deletion test).
#
# Everything that is NOT those two files is byte-identical across variants, and all three
# run in ONE dispatch on ONE runner with ONE toolchain, ONE CARGO_TARGET_DIR and
# GUNBC_NATIVE_PRODUCT_REUSE=fresh -- so the only difference is the algorithm under test.
# 3ead368 numbers are historical only; control is measured here.
set -u
echo "############ AB start $(date -u +%H:%M:%S)"
echo "head=$(git rev-parse HEAD 2>/dev/null || echo NO-GIT) host=$(hostname) arch=$(uname -m)"
echo "rustc=$(rustc -vV 2>/dev/null | head -2 | tr '\n' ' ')"
export GUNBC_NATIVE_PRODUCT_REUSE=fresh
export CARGO_TARGET_DIR=${CARGO_TARGET_DIR:-/root/sd503_ab_target}
mkdir -p "$CARGO_TARGET_DIR"
TREE=$PWD
DAG=src/v1/04_infer.dag
MIRROR=src/v1/stage0/src/v1_compiler_infer.rs
for f in .sdm/pairs/control/04_infer.dag .sdm/pairs/control/v1_compiler_infer.rs \
         .sdm/dag_variants/keep/04_infer.dag .sdm/dag_variants/delete/04_infer.dag \
         .sdm/gen_keep_v1_compiler_infer.rs .sdm/gen_delete_v1_compiler_infer.rs \
         .sdm/gap_block.rs .sdm/hooks.py .sdm/measure_variant.sh; do
  [ -f "$f" ] || { echo "MISSING $f"; exit 2; }
done
# Fixtures must live in exactly ONE directory under the source root: source discovery
# refuses the whole compile when a module path is declared by two files.
cp .sdm/fixtures/gap_depth_*.dag .sdm/fixtures/garr_*.dag dag/test/
rm -rf .sdm/fixtures
echo "fixtures staged: $(ls dag/test/gap_depth_*.dag dag/test/garr_*.dag | wc -l) files, .sdm/fixtures=$([ -d .sdm/fixtures ] && echo YES-BUG || echo gone)"
marks() {
  printf "gate=%s contains=%s stale=%s planned=%s recheck=%s sm_after=%s" \
    "$(grep -c 'fn call_needs_generic_rebinding_pass' "$1" || true)" \
    "$(grep -c 'fn expr_contains_lambda' "$1" || true)" \
    "$(grep -c 'fn typed_expr_is_stale' "$1" || true)" \
    "$(grep -c 'fn infer_planned_lambda_recheck' "$1" || true)" \
    "$(grep -c 'fn argument_needs_generic_recheck' "$1" || true)" \
    "$(grep -c 'still_missing_after' "$1" || true)"
}
compose() { # variant
  case "$1" in
    control)   cp .sdm/pairs/control/04_infer.dag "$DAG";               cp .sdm/pairs/control/v1_compiler_infer.rs "$MIRROR" ;;
    keep)      cp .sdm/dag_variants/keep/04_infer.dag "$DAG";           cp .sdm/gen_keep_v1_compiler_infer.rs "$MIRROR" ;;
    delete)    cp .sdm/dag_variants/delete/04_infer.dag "$DAG";         cp .sdm/gen_delete_v1_compiler_infer.rs "$MIRROR" ;;
    *) echo "UNKNOWN VARIANT $1"; return 2 ;;
  esac
  echo "COMPOSED $1 dag($(marks $DAG)) mirror($(marks $MIRROR))"
  # The authority check: control must actually carry the OLD algorithm and the treatments
  # must actually lack it, or the A/B measures nothing.
  if [ "$1" = control ]; then
    [ "$(grep -c 'fn call_needs_generic_rebinding_pass' $DAG)" = 1 ] || { echo "CONTROL-NOT-OLD-ALGORITHM"; return 3; }
    [ "$(grep -c 'fn typed_expr_is_stale' $DAG)" = 0 ] || { echo "CONTROL-HAS-NEW-STATE-PREDICATE"; return 3; }
  else
    [ "$(grep -c 'fn call_needs_generic_rebinding_pass' $DAG)" = 0 ] || { echo "TREATMENT-STILL-HAS-GATE"; return 3; }
    [ "$(grep -c 'still_missing_after' $DAG)" -ge 1 ] || { echo "TREATMENT-LOST-SPARSE-FOLD"; return 3; }
  fi
}
build() { # variant
  echo "building $1 $(date -u +%H:%M:%S)"
  ( cargo build --release -j 8 -p v1-compiler --bin gunbc --bin claim_batch > /tmp/build_$1.log 2>&1
    echo "BUILD_RC=$?" >> /tmp/build_$1.log ) &
  bp=$!
  while kill -0 $bp 2>/dev/null; do sleep 30; echo "hb-build $1 $(wc -l < /tmp/build_$1.log 2>/dev/null || echo 0) lines $(date -u +%H:%M:%S)"; done
  wait $bp || true
  if ! grep -q "^BUILD_RC=0$" /tmp/build_$1.log 2>/dev/null; then
    echo "BUILD-FAILED $1 rc_line=$(grep -c '^BUILD_RC=' /tmp/build_$1.log 2>/dev/null || echo none)"
    echo "mem: $(free -m | awk 'NR==2{print "total="$2"MB avail="$7"MB"}')"
    echo "log-signal-lines: $(grep -icE 'killed|signal|no space|error\[' /tmp/build_$1.log 2>/dev/null || echo 0)"
    tail -50 /tmp/build_$1.log
    return 1
  fi
  B="$CARGO_TARGET_DIR/release/gunbc"
  [ -x "$B" ] || { echo "BUILD-OK-NO-BINARY $B"; return 1; }
  echo "built $1 $(date -u +%H:%M:%S) bin_sha256=$(sha256sum "$B" | cut -d' ' -f1) bytes=$(stat -c %s "$B")"
}
# Variant list comes from argv so a dispatch stays well inside the runner's action window
# (bb --timeout 45m; output is buffered until the action ends, so an overlong action that
# dies loses EVERYTHING, including results already measured). The authoritative A/B pairs
# control with keep and repeats control, all in one dispatch on one runner:
#   dispatch 1: control keep control2      (A/B + repeatability)
#   dispatch 2: delete                     (the item-5 deletion test)
# control2 re-measures the tree control already composed, so it skips the hook re-apply
# (which is correctly fail-closed against re-application) and prints the instrument sha.
START=$(date +%s)
rc_all=0
VARIANTS="${*:-control keep control2}"
for VRAW in $VARIANTS; do
  V="$VRAW"; SKIPHOOK=no
  [ "$V" = control2 ] && { V=control; SKIPHOOK=yes; }
  ELAPSED=$(( $(date +%s) - START ))
  # Variants are ordered by importance: control and keep are the required A/B, delete is
  # the item-5 deletion test. Past the guard the remaining variants are SKIPPED with a
  # printed reason rather than risking the results already measured.
  if [ $ELAPSED -gt 1800 ]; then
    echo "VARIANT-SKIPPED $V($VRAW) elapsed=${ELAPSED}s (window guard)"; rc_all=1; continue
  fi
  echo "@@@@ VARIANT=$V start $(date -u +%H:%M:%S) elapsed=${ELAPSED}s"
  if [ "$SKIPHOOK" = no ]; then
    compose "$V" || { echo "COMPOSE-FAILED $V"; rc_all=1; continue; }
    case "$V" in control) SIDE=control ;; *) SIDE=treatmentB ;; esac
    echo "hook side for $V = $SIDE"
    python3 .sdm/hooks.py "$SIDE" .sdm/gap_block.rs "$MIRROR" src/v1/stage0/src/v1_compiler_compile.rs \
      || { echo "HOOK-FAILED $V"; rc_all=1; continue; }
  else
    echo "instrument reused; mirror sha256=$(sha256sum $MIRROR | cut -d' ' -f1)"
  fi
  build "$V" || { echo "VARIANT-SKIPPED-BUILD-FAILED $V"; rc_all=1; continue; }
  # Only the two A/B variants emit the v2 closure (two more heavy compiles each); the
  # repeat and the item-5 variant skip it.
  case "$VRAW" in control|keep) export CLOSURES=yes ;; *) export CLOSURES=no ;; esac
  echo "closures for $VRAW = $CLOSURES"
  bash .sdm/measure_variant.sh "$V" || { echo "MEASURE-REPORTED-FAILURE $V"; rc_all=1; }
done
echo "variants measured: $VARIANTS"
echo "############ AB done $(date -u +%H:%M:%S) rc_all=$rc_all elapsed=$(( $(date +%s) - START ))s"
exit $rc_all
